INSERT INTO thong_bao (ngay, ten_thong_bao, noi_dung, nguoi_tao_id) VALUES
  ('2026-11-03', 'Quy định mới về hồ sơ ký gửi', 'Từ ngày 05/11, mọi hồ sơ ký gửi bất động sản phải có bản sao giấy tờ pháp lý và ảnh chụp thực tế trước khi đăng tin.', 101),
  ('2026-11-06', 'Đào tạo kỹ năng tư vấn khách hàng', 'Phòng nhân sự tổ chức buổi đào tạo kỹ năng tư vấn vào 14:00 thứ Sáu 07/11 tại phòng họp tầng 3. Nhân viên kinh doanh bắt buộc tham dự.', 101),
  ('2026-11-10', 'Chương trình ưu đãi phí môi giới tháng 11', 'Giảm 10% phí môi giới cho giao dịch ký hợp đồng trong tháng 11. Áp dụng cho khách hàng mới.', 101),
  ('2026-11-13', 'Bảo trì hệ thống ngày 15/11', 'Hệ thống tạm dừng từ 22:00 đến 23:30 thứ Bảy 15/11 để nâng cấp. Vui lòng lưu công việc trước thời gian này.', 101),
  ('2026-11-17', 'Họp giao ban tuần', 'Họp giao ban lúc 8:30 thứ Hai hàng tuần tại phòng họp tầng 2, báo cáo số khách mới và giao dịch đang theo dõi.', 101),
  ('2026-11-18', 'Lịch trực cuối tuần tháng 11', 'Văn phòng mở cửa thứ Bảy từ 8:00 đến 17:00 để tiếp khách xem nhà. Lịch trực từng người gửi qua email.', 101);
